// Define competitor keywords and topics to monitor
const monitoringTopics = [
  'NVIDIA H100 availability',
  'AMD MI300X pricing',
  'Intel Gaudi launch',
  'GPU supply chain disruption',
  'TSMC allocation priority',
  'AWS GPU instances',
  'Azure OpenAI GPU',
  'Google Cloud TPU'
];

return monitoringTopics.map(topic => ({
  json: {
    search_query: topic,
    timestamp: new Date().toISOString()
  }
}));

const newsData = $input.first().json;
const searchQuery = $('Define Search Topics').item.json.search_query;

if (!newsData.articles || newsData.articles.length === 0) {
  return [];
}

// Filter for significant news (from reputable sources)
const significantSources = [
  'techcrunch', 'reuters', 'bloomberg', 'wsj', 'ft',
  'theverge', 'arstechnica', 'wired', 'engadget'
];

const relevantArticles = newsData.articles
  .filter(article => {
    const source = article.source?.id || article.source?.name?.toLowerCase() || '';
    return significantSources.some(s => source.includes(s));
  })
  .slice(0, 3); // Top 3 most recent

if (relevantArticles.length === 0) {
  return [];
}

return [{
  json: {
    topic: searchQuery,
    article_count: relevantArticles.length,
    articles: relevantArticles.map(a => ({
      title: a.title,
      description: a.description,
      url: a.url,
      source: a.source.name,
      published: a.publishedAt
    })),
    timestamp: new Date().toISOString()
  }
}];

